<?php declare(strict_types=1);require_once __DIR__.'/includes/store.php';$user=require_customer();$pageTitle='My account';$errors=[];$message='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_is_valid($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid form token.');}$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));if($name==='')$errors[]='Name is required.';$profilePath=$user['profile_image']??null;if(!empty($_FILES['profile_image']['name'])){$f=$_FILES['profile_image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>3*1024*1024)$errors[]='Profile image must be 3 MB or smaller.';else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)$errors[]='Use a JPG, PNG or WEBP profile image.';else{$dir=__DIR__.'/uploads/profiles';if(!is_dir($dir))mkdir($dir,0755,true);$file=bin2hex(random_bytes(12)).'.'.$ext;if(move_uploaded_file($f['tmp_name'],$dir.'/'.$file))$profilePath='uploads/profiles/'.$file;else $errors[]='Could not save profile image.';}}}if(!$errors){$pdo->prepare('UPDATE users SET full_name=?,phone=?,profile_image=? WHERE id=?')->execute([$name,$phone?:null,$profilePath,$user['id']]);$message='Profile updated.';$user=require_customer();}}$s=$pdo->prepare('SELECT order_number,status,payment_status,total_amount,placed_at FROM orders WHERE user_id=? ORDER BY placed_at DESC LIMIT 20');$s->execute([$user['id']]);$orders=$s->fetchAll();require __DIR__.'/includes/header.php';?><section class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2"><div><h1 class="h2">My account</h1><p class="text-secondary">Manage your details and track your orders.</p></div><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-outline-secondary">Log out</button></form></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><div class="row g-4"><div class="col-lg-4"><form method="post" enctype="multipart/form-data" class="card border-0 shadow-sm p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><h2 class="h5">Profile details</h2><label class="form-label">Name</label><input class="form-control mb-3" name="full_name" value="<?=e($user['full_name'])?>" required><label class="form-label">Email</label><input class="form-control mb-3" value="<?=e($user['email'])?>" disabled><label class="form-label">Phone</label><input class="form-control mb-3" name="phone" value="<?=e((string)$user['phone'])?>"><label class="form-label">Profile image</label><?php if(!empty($user['profile_image'])):?><img src="<?=e($user['profile_image'])?>" alt="Profile" class="header-avatar mb-2"><?php endif;?><input class="form-control mb-3" type="file" name="profile_image" accept="image/jpeg,image/png,image/webp"><small class="text-secondary mb-3">JPG, PNG or WEBP, maximum 3 MB.</small><button class="btn btn-primary">Save changes</button></form></div><div class="col-lg-8"><div class="card border-0 shadow-sm p-4"><h2 class="h5">Recent orders</h2><?php if(!$orders):?><p class="text-secondary mb-0">No orders yet. <a href="shop.php">Start shopping</a>.</p><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Order status</th><th>Payment</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['placed_at'])?></td><td><?=money($o['total_amount'])?></td><td><?=e($o['status'])?></td><td><?=e($o['payment_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></div></section><?php require __DIR__.'/includes/footer.php';?>
